UPDATE public.beaches b SET lat=(s->>'latitude')::double precision,lon=(s->>'longitude')::double precision,
  swell_window_center_deg=(s#>>'{beach,swell_window_center_deg}')::double precision,
  swell_window_halfwidth_deg=(s#>>'{beach,swell_window_halfwidth_deg}')::double precision,
  swell_access_factors=CASE WHEN jsonb_typeof(s#>'{beach,swell_access_factors}')='array' THEN
    ARRAY(SELECT jsonb_array_elements_text(s#>'{beach,swell_access_factors}')::double precision) END,
  terrain_enabled=(s#>>'{beach,terrain_enabled}')::boolean,
  deepwater_decay_factor=(s#>>'{beach,deepwater_decay_factor}')::double precision,
  shoaling_factors=nullif(s#>'{beach,shoaling_factors}','null'::jsonb)
FROM public.study_refresh_original a,jsonb_array_elements(a.scope_inputs) s WHERE b.id=(s->>'sourcePointId')::uuid;
INSERT INTO public.swell_watch_study_authorities SELECT * FROM public.study_refresh_original;
CREATE FUNCTION public.study_refresh_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'refresh assertion failed: %',label; END IF; END; $$;
CREATE FUNCTION public.study_refresh_receipt(run_at timestamptz) RETURNS jsonb LANGUAGE sql AS $$
 SELECT public.fixture_study_catalog_scopes(to_char(run_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI"Z"'),1.2,1,
 ARRAY(SELECT (s->>'sourcePointId')::uuid FROM public.study_refresh_original a,jsonb_array_elements(a.cohort) s));
$$;
CREATE TABLE public.study_refresh_run AS SELECT to_timestamp(floor(extract(epoch FROM now())/21600)*21600)-interval '6 hours' run_at;
CREATE TABLE public.study_refresh_ids AS SELECT r.* FROM public.study_refresh_run t,
 LATERAL public.record_swell_watch_provider_run_receipt(public.study_refresh_receipt(t.run_at)) r;
DO $$
DECLARE a public.swell_watch_study_authorities; c record; output jsonb;
BEGIN
 SELECT * INTO a FROM public.swell_watch_study_authorities WHERE epoch=1;
 SELECT * INTO c FROM public.complete_swell_watch_study_run((SELECT revision_set_id FROM public.study_refresh_ids),a.policy_hash,a.cohort,a.scope_inputs);
 output:=jsonb_build_object('providerBatchId',c.provider_batch_id,'policyHash',a.policy_hash,'status','suppressed','reason','missing_partition',
 'enqueued',0,'sendEligibility','not_evaluated','scopeOutcomes',(SELECT jsonb_agg(jsonb_build_object('sourcePointId',s->>'sourcePointId','status','suppressed','reason','missing_partition')) FROM jsonb_array_elements(a.cohort) s));
 PERFORM public.record_swell_watch_study_evaluation(c.provider_batch_id,a.policy_hash,output,a.scope_inputs);
END; $$;
CREATE TABLE public.study_refresh_history AS SELECT
 (SELECT jsonb_agg(to_jsonb(a)) FROM public.swell_watch_study_acceptances a) acceptances,
 (SELECT jsonb_agg(to_jsonb(e)) FROM public.swell_watch_study_evaluations e) evaluations;
SELECT public.study_refresh_assert((public.read_swell_watch_study_health()->>'suppressedAttempts')::integer=1,'old epoch has accounting');
UPDATE public.beaches SET lon=-122.51229 WHERE id='e8a921b7-c2b5-4259-9e5c-bd06765f7ae4';
